
const WORDS=[{"id": 0, "w": "闹钟", "p": "nàozhōng", "t": "名词", "m": "đồng hồ báo thức", "coll": "设置闹钟、闹钟响了", "s": "我把闹钟设在了早上七点。"}, {"id": 1, "w": "危害", "p": "wēihài", "t": "动词", "m": "gây nguy hại, làm hại", "coll": "危害健康、危害环境", "s": "乱扔垃圾的行为会危害周围的环境。"}, {"id": 2, "w": "人类", "p": "rénlèi", "t": "名词", "m": "loài người", "coll": "人类社会、人类历史", "s": "这本书介绍了人类社会的发展过程。"}, {"id": 3, "w": "机制", "p": "jīzhì", "t": "名词", "m": "cơ chế", "coll": "运行机制、建立机制", "s": "会议上，负责人介绍了这套管理机制。"}, {"id": 4, "w": "生物", "p": "shēngwù", "t": "名词", "m": "sinh vật", "coll": "海洋生物、生物种类", "s": "这本书介绍了许多生活在海洋里的生物。"}, {"id": 5, "w": "规律", "p": "guīlǜ", "t": "名词／形容词", "m": "quy luật; đều đều, có nhịp điệu", "coll": "生活规律、变化规律", "s": "她每天按时吃饭、按时休息，生活很规律。"}, {"id": 6, "w": "光线", "p": "guāngxiàn", "t": "名词", "m": "ánh sáng, tia sáng", "coll": "光线充足、光线柔和", "s": "这间教室光线充足，很适合阅读。"}, {"id": 7, "w": "必要", "p": "bìyào", "t": "形容词", "m": "cần thiết, thiết yếu", "coll": "有必要、必要的准备", "s": "出发前，我们有必要检查一下行李。"}, {"id": 8, "w": "过渡", "p": "guòdù", "t": "动词", "m": "quá độ, chuyển tiếp", "coll": "逐渐过渡、过渡阶段", "s": "老师先讲简单的例子，再逐渐过渡到较难的内容。"}, {"id": 9, "w": "浅", "p": "qiǎn", "t": "形容词", "m": "nông, cạn", "coll": "水很浅、浅蓝色", "s": "这条小河的水很浅，能看见河底的石头。"}, {"id": 10, "w": "现代", "p": "xiàndài", "t": "名词／形容词", "m": "thời đại ngày nay; hiện đại", "coll": "现代生活、现代技术", "s": "现代技术给我们的日常生活带来了许多方便。"}, {"id": 11, "w": "享受", "p": "xiǎngshòu", "t": "动词", "m": "hưởng thụ", "coll": "享受生活、享受阳光", "s": "周末，我们坐在阳台上，享受温暖的阳光。"}, {"id": 12, "w": "用途", "p": "yòngtú", "t": "名词", "m": "công dụng", "coll": "不同用途、用途广泛", "s": "老师向大家介绍了这种工具的不同用途。"}, {"id": 13, "w": "实验", "p": "shíyàn", "t": "动词／名词", "m": "thực nghiệm; công việc thực nghiệm", "coll": "做实验、实验结果", "s": "同学们正在老师的指导下做实验。"}, {"id": 14, "w": "铃", "p": "líng", "t": "名词", "m": "cái chuông", "coll": "门铃、铃响了", "s": "门口的铃响了，她起身去开门。"}, {"id": 15, "w": "所", "p": "suǒ", "t": "助词", "m": "(được dùng trước động từ của kết cấu chữ 的 làm định ngữ)", "coll": "所见所闻、所需要的", "s": "这正是我所需要的资料。"}, {"id": 16, "w": "状态", "p": "zhuàngtài", "t": "名词", "m": "trạng thái, tình trạng", "coll": "学习状态、工作状态", "s": "休息了一会儿，他又恢复了良好的工作状态。"}, {"id": 17, "w": "清醒", "p": "qīngxǐng", "t": "形容词／动词", "m": "tỉnh táo; tỉnh lại", "coll": "头脑清醒、保持清醒", "s": "讨论这个问题时，我们需要保持清醒的头脑。"}, {"id": 18, "w": "呼吸", "p": "hūxī", "t": "动词", "m": "hít thở", "coll": "深深地呼吸、呼吸新鲜空气", "s": "她站在窗前，深深地呼吸了一口新鲜空气。"}, {"id": 19, "w": "心理", "p": "xīnlǐ", "t": "名词", "m": "tâm lý", "coll": "心理活动、心理变化", "s": "这篇小说细致地描写了人物的心理变化。"}, {"id": 20, "w": "慌张", "p": "huāngzhāng", "t": "形容词", "m": "luống cuống, bối rối", "coll": "不要慌张、神色慌张", "s": "发现找不到车票时，她显得有些慌张。"}, {"id": 21, "w": "情绪", "p": "qíngxù", "t": "名词", "m": "tâm trạng, tinh thần", "coll": "情绪低落、调整情绪", "s": "看到熟悉的朋友，她的情绪渐渐好起来了。"}, {"id": 22, "w": "低落", "p": "dīluò", "t": "形容词", "m": "suy nhược, ủ rũ", "coll": "心情低落、情绪低落", "s": "比赛失利以后，他有一段时间情绪比较低落。"}, {"id": 23, "w": "记忆", "p": "jìyì", "t": "动词／名词", "m": "nhớ; ký ức", "coll": "美好的记忆、记忆中的家乡", "s": "这张老照片让我想起了童年的美好记忆。"}, {"id": 24, "w": "计算", "p": "jìsuàn", "t": "动词", "m": "tính toán", "coll": "计算费用、计算结果", "s": "出发前，我们先计算了一下旅行费用。"}, {"id": 25, "w": "相当", "p": "xiāngdāng", "t": "动词", "m": "tương đương với, ngang nhau", "coll": "水平相当、实力相当", "s": "这两支球队实力相当，比赛非常精彩。"}, {"id": 26, "w": "持续", "p": "chíxù", "t": "动词", "m": "kéo dài, duy trì lâu dài", "coll": "持续三天、持续增长", "s": "这场大雨已经持续了三个小时。"}, {"id": 27, "w": "数", "p": "shù", "t": "数词", "m": "vài, mấy", "coll": "数百人、数日之后", "s": "数百人参加了今天下午的文化活动。"}, {"id": 28, "w": "导致", "p": "dǎozhì", "t": "动词", "m": "dẫn đến, gây ra", "coll": "导致失败、导致误会", "s": "信息不准确，可能会导致不必要的误会。"}, {"id": 29, "w": "失眠", "p": "shīmián", "t": "动词", "m": "mất ngủ", "coll": "经常失眠、昨晚失眠", "s": "他昨晚失眠了，直到很晚才睡着。"}, {"id": 30, "w": "精神", "p": "jīngshén", "t": "名词／形容词", "m": "tinh thần; sôi nổi, hoạt bát", "coll": "精神很好、精神状态", "s": "休息了一晚，她今天看起来很精神。"}, {"id": 31, "w": "专家", "p": "zhuānjiā", "t": "名词", "m": "chuyên gia", "coll": "一位专家、请教专家", "s": "这位专家用简单的语言回答了大家的问题。"}, {"id": 32, "w": "采用", "p": "cǎiyòng", "t": "动词", "m": "chọn dùng, áp dụng", "coll": "采用方法、采用建议", "s": "经过讨论，我们决定采用她提出的方法。"}, {"id": 33, "w": "柔和", "p": "róuhé", "t": "形容词", "m": "êm dịu", "coll": "柔和的灯光、声音柔和", "s": "房间里的灯光十分柔和，让人觉得很舒服。"}, {"id": 34, "w": "愿望", "p": "yuànwàng", "t": "名词", "m": "ước muốn, điều mong muốn", "coll": "实现愿望、美好的愿望", "s": "她终于实现了去中国学习的愿望。"}, {"id": 35, "w": "窗帘", "p": "chuānglián", "t": "名词", "m": "rèm cửa sổ", "coll": "拉开窗帘、关上窗帘", "s": "早上起床后，他先拉开了窗帘。"}, {"id": 36, "w": "市场", "p": "shìchǎng", "t": "名词", "m": "thị trường, chợ", "coll": "市场变化、农贸市场", "s": "这个市场里出售各种新鲜的蔬菜和水果。"}, {"id": 37, "w": "产品", "p": "chǎnpǐn", "t": "名词", "m": "sản phẩm", "coll": "新产品、产品质量", "s": "这家公司每年都会推出一些新产品。"}, {"id": 38, "w": "模仿", "p": "mófǎng", "t": "动词", "m": "mô phỏng, bắt chước", "coll": "模仿动作、模仿发音", "s": "学发音时，我们可以模仿老师的口型。"}, {"id": 39, "w": "避免", "p": "bìmiǎn", "t": "动词", "m": "tránh, ngăn ngừa", "coll": "避免误会、避免浪费", "s": "提前说明情况，可以避免不必要的误会。"}, {"id": 40, "w": "传统", "p": "chuántǒng", "t": "名词／形容词", "m": "truyền thống; (thuộc) truyền thống", "coll": "传统文化、传统节日", "s": "年轻人也应该了解和尊重传统文化。"}];
